function assumptionStyle(){if(document.getElementById('pgAssumptionStyle'))return;var s=document.createElement('style');s.id='pgAssumptionStyle';s.textContent='.pg-estimator-assumptions{margin-top:16px;border:1px solid rgba(255,255,255,.12);border-radius:16px;padding:12px}.pg-estimator-assumptions summary{min-height:44px;display:flex;align-items:center;cursor:pointer;font-weight:800}.pg-estimator-assumptions fieldset{margin-top:12px;border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:12px}.pg-estimator-assumptions input,.pg-estimator-assumptions select{box-sizing:border-box;width:100%;min-height:44px;margin-top:5px;border:1px solid rgba(255,255,255,.15);border-radius:11px;background:#102938;color:#fff;padding:8px}@media(max-width:320px){.pg-estimator-grid{grid-template-columns:1fr}.pg-estimator-grid .pg-estimator-field{grid-column:1!important}}';document.head.appendChild(s);}
function options(selected){return '<option value="">Select a PourGrid product</option>'+products().map(function(p){return '<option value="'+esc(p.name)+'"'+(p.name===selected?' selected':'')+'>'+esc(p.name)+'</option>';}).join('');}
function sharedOptions(selected){return '<option value="">Select a shared ingredient</option>'+definitions.map(function(d){return '<option value="'+esc(d.id)+'"'+(d.id===selected?' selected':'')+'>'+esc(d.name)+(d.result_kind==='estimated'?' · estimated':'')+'</option>';}).join('');}
function row(item,i){var legacy=item.source==='custom'&&item.name,d=item.source==='shared'?definition(item.ingredientId):null,entry=catalogEntryFor(item),cost=d?definitionCost(d):item.unitCost==null||item.unitCost===''?null:Number(item.unitCost),selected=entry?entry.id:'',category=item.catalogCategory||entry&&entry.category||unifiedCatalog()[0]&&unifiedCatalog()[0].category||'',whole=item.unit==='each'||item.unit==='piece'||item.unit==='flat',presets=whole?[1,2,3,4,6,8]:[.25,.5,.75,1,1.25,1.5,2],step=whole?1:.25,complete=ingredientComplete(item),expanded=expandedRows.has(i)||!complete,line=calculate({target:18,ingredients:[item]}),lineCost=line.missing.length?null:line.total,name=item.name||item.productName||'Choose an item';return '<article class="pg-estimator-row'+(expanded?' expanded':' collapsed')+'" data-index="'+i+'"><button class="pg-ingredient-summary" type="button" data-toggle-row="'+i+'" aria-expanded="'+expanded+'" aria-label="'+(expanded?'Collapse ':'Edit ')+esc(name)+'"><span><strong>'+esc(name)+'</strong><small>'+esc(item.amount)+' '+esc(item.unit)+'</small></span><span class="pg-ingredient-cost">'+(Number.isFinite(lineCost)?ingredientMoney(lineCost):costLabel(d,cost))+'</span><b aria-hidden="true">⌄</b></button><div class="pg-ingredient-editor"'+(expanded?'':' hidden')+'><div class="pg-estimator-rowtop"><div class="pg-estimator-grid"><div class="pg-estimator-field" style="margin-top:0"><label>Category</label><select data-field="catalogCategory" aria-label="Category for ingredient '+(i+1)+'">'+categoryOptions(category)+'</select></div><div class="pg-estimator-field" style="margin-top:0;grid-column:span 2"><label>Item</label><select data-field="catalogItem" aria-label="Item for ingredient '+(i+1)+'">'+itemOptions(category,selected)+'</select></div></div><button class="pg-estimator-remove" type="button" data-remove="'+i+'" aria-label="Remove ingredient '+(i+1)+'">×</button></div>'+(legacy?'<p class="pg-estimator-note"><strong>Legacy custom ingredient:</strong> '+esc(item.name)+'. It remains readable; choose a catalog item to replace it.</p>':'')+'<div class="pg-estimator-field"><label>Amount</label><div class="pg-estimator-actions pg-amount-controls">'+presets.map(function(v){return'<button class="pg-estimator-btn secondary" type="button" data-amount="'+v+'" aria-pressed="'+(Number(item.amount)===v)+'">'+v+'</button>'}).join('')+'<button class="pg-estimator-btn secondary" type="button" data-amount-step="-'+step+'" aria-label="Decrease amount">−</button><strong aria-live="polite">'+esc(item.amount)+' '+esc(item.unit)+'</strong><button class="pg-estimator-btn secondary" type="button" data-amount-step="'+step+'" aria-label="Increase amount">+</button></div><details><summary>Advanced amount</summary><input data-field="amount" type="number" min="'+(whole?'1':'0.001')+'" step="'+step+'" inputmode="decimal" value="'+esc(item.amount)+'" aria-label="Advanced amount for ingredient '+(i+1)+'"></details></div><div class="pg-estimator-grid"><div class="pg-estimator-field"><label>Unit</label><select data-field="unit">'+['oz','ml','tsp','tbsp','each','piece','flat'].map(function(u){return'<option value="'+u+'"'+(item.unit===u?' selected':'')+'>'+u+'</option>'}).join('')+'</select></div><div class="pg-estimator-field" style="grid-column:span 2"><label>Cost status</label><input disabled value="'+(costLabel(d,cost))+'"></div></div>'+(d&&d.result_kind==='estimated'?'<p class="pg-estimator-note"><strong>Estimated cost.</strong> '+esc(d.assumption_note)+'</p>':'')+'<div class="pg-estimator-actions pg-row-actions"><button class="pg-estimator-btn secondary" data-up="'+i+'" type="button" aria-label="Move ingredient up">↑</button><button class="pg-estimator-btn secondary" data-down="'+i+'" type="button" aria-label="Move ingredient down">↓</button><button class="pg-estimator-btn secondary" data-duplicate-row="'+i+'" type="button">Duplicate</button><button class="pg-estimator-btn secondary" data-replace="'+i+'" type="button">Replace</button></div></div></article>';}
function assumptions(){return '<details class="pg-estimator-assumptions"><summary>Ingredient cost assumptions</summary><p class="pg-estimator-note">Update a shared ingredient once; every recipe referencing it recalculates automatically.</p>'+definitions.map(function(d){return '<fieldset data-definition="'+esc(d.id)+'"><legend>'+esc(d.name)+' · '+esc(d.result_kind)+'</legend><div class="pg-estimator-grid"><label>Case price<input data-def="packageCasePrice" type="number" min="0" step="0.01" value="'+esc(d.package_case_price==null?'':d.package_case_price)+'" placeholder="Invoice price needed"></label><label>Packages / case<input data-def="packagesPerCase" type="number" min="0.001" step="0.001" value="'+esc(d.packages_per_case)+'"></label><label>Usable units / package<input data-def="estimatedUnitsPerPackage" type="number" min="0.001" step="0.001" value="'+esc(d.estimated_units_per_package==null?'':d.estimated_units_per_package)+'"></label><label>Prep yield<input data-def="preparationYield" type="number" min="0.001" step="0.001" value="'+esc(d.preparation_yield)+'"></label><label>Waste %<input data-def="wastePercent" type="number" min="0" max="95" step="0.1" value="'+esc(d.waste_percent)+'"></label><label>Confidence<select data-def="resultKind"><option value="estimated"'+(d.result_kind==='estimated'?' selected':'')+'>Estimated</option><option value="exact"'+(d.result_kind==='exact'?' selected':'')+'>Exact</option></select></label></div><p class="pg-estimator-note">'+esc(d.assumption_note)+'</p>'+(d.can_edit?'<button class="pg-estimator-btn secondary" data-save-definition="'+esc(d.id)+'" type="button">Save assumptions</button>':'')+'</fieldset>';}).join('')+'</details>';}
function render(){var root=document.getElementById('pgEstimator');if(!root)return;var calc=calculate(draft);root.innerHTML='<section class="pg-estimator-panel" role="dialog" aria-modal="true" aria-labelledby="pgEstimatorTitle"><div class="pg-estimator-grab" aria-hidden="true"></div><header class="pg-estimator-head"><div><small>POURGRID PRICING</small><h2 id="pgEstimatorTitle">Profit Lab</h2><p>Build drinks. Understand cost. Price with confidence.</p></div><button class="pg-estimator-close" type="button" aria-label="Close Profit Lab">×</button></header><div class="pg-estimator-field"><label for="pgDrinkName">Drink name</label><input id="pgDrinkName" value="'+esc(draft.name)+'" placeholder="e.g. Painkiller"></div><div id="pgEstimatorIngredients">'+draft.ingredients.map(row).join('')+'</div><div class="pg-estimator-actions"><button id="pgEstimatorAdd" class="pg-estimator-btn secondary" type="button">+ Add ingredient</button></div>'+assumptions()+'<div class="pg-estimator-field"><label for="pgTarget">Target cost: <strong id="pgTargetValue">'+esc(draft.target)+'%</strong></label><input id="pgTarget" class="pg-estimator-range" type="range" min="5" max="40" step="1" value="'+esc(draft.target)+'"><p class="pg-estimator-note">Move left for a lower cost percentage and higher selling price. Move right for a higher percentage and lower selling price.</p></div><div class="pg-estimator-field"><label for="pgMenuPrice">Current or planned menu price (optional)</label><input id="pgMenuPrice" type="number" min="0.01" step="0.25" inputmode="decimal" value="'+esc(draft.menuPrice)+'" placeholder="0.00"></div><div class="pg-estimator-results" aria-live="polite"><div class="pg-estimator-metrics"><div class="pg-estimator-metric"><span>Recipe cost</span><strong>'+money(calc.missing.length?NaN:calc.total)+'</strong></div><div class="pg-estimator-metric"><span>Recommended price</span><strong>'+money(calc.missing.length?NaN:calc.suggested)+'</strong></div><div class="pg-estimator-metric"><span>Actual cost %</span><strong>'+(calc.actual==null||calc.missing.length?'—':calc.actual.toFixed(1)+'%')+'</strong></div></div><p class="pg-estimator-note">Recommended price = total recipe cost ÷ target percentage.'+(calc.estimated.length?' Includes estimated yield: '+esc(calc.estimated.join(', '))+'.':'')+'</p></div>'+(error?'<p class="pg-estimator-note pg-estimator-error" role="alert">'+esc(error)+'</p>':'')+'<div class="pg-estimator-actions"><button id="pgEstimatorSave" class="pg-estimator-btn" type="button"'+(saving?' disabled':'')+'>'+(saving?'Saving…':draft.id?'Update shared recipe':'Save shared recipe')+'</button><button id="pgEstimatorNew" class="pg-estimator-btn secondary" type="button">New</button>'+(draft.id?'<button id="pgEstimatorDuplicate" class="pg-estimator-btn secondary" type="button">Duplicate</button>':'')+'</div><section class="pg-estimator-saved"><h3>Shared recipes</h3>'+(loading?'<p class="pg-estimator-note">Loading Profit Lab…</p>':recipes.length?recipes.map(function(x){var c=calculate(x);return '<article><div><strong>'+esc(x.name)+'</strong><div class="pg-estimator-note">'+x.ingredients.length+' ingredients · '+money(c.missing.length?NaN:c.total)+' cost · '+money(c.missing.length?NaN:c.suggested)+' recommended · v'+x.version+'</div></div><div><button class="pg-estimator-btn secondary" data-edit="'+esc(x.id)+'" type="button">Edit</button> '+(x.canDelete?'<button class="pg-estimator-btn secondary" data-delete="'+esc(x.id)+'" type="button" aria-label="Delete '+esc(x.name)+'">Delete</button>':'')+'</div></article>';}).join(''):'<p class="pg-estimator-note">No shared recipes yet.</p>')+'</section></section>';bind(root);}
function renderComplete(){var root=document.getElementById('pgEstimator');if(!root)return;var c=calculate(draft),duplicates={};draft.ingredients.forEach(function(i){var n=(i.name||i.productName||'').toLowerCase();if(n)duplicates[n]=(duplicates[n]||0)+1;});var duplicateNames=Object.keys(duplicates).filter(function(n){return duplicates[n]>1;});root.innerHTML='<section class="pg-estimator-panel" role="dialog" aria-modal="true" aria-labelledby="pgEstimatorTitle"><div class="pg-estimator-grab"></div><header class="pg-estimator-head"><div><small>PROFIT LAB</small><h2 id="pgEstimatorTitle">'+(mode==='quick'?'Quick Estimate':'Saved Recipe')+'</h2><p>Nothing is saved unless you deliberately save it.</p></div><button class="pg-estimator-close" type="button" aria-label="Close Profit Lab">×</button></header><div class="pg-estimator-actions"><button id="pgQuickEntry" class="pg-estimator-btn '+(mode==='quick'?'':'secondary')+'" type="button">Quick Estimate</button><button id="pgSavedEntry" class="pg-estimator-btn '+(mode==='saved'?'':'secondary')+'" type="button">Saved Recipes</button></div><div class="pg-estimator-field"><label for="pgDrinkName">Recipe name '+(mode==='quick'?'(optional until saved)':'')+'</label><input id="pgDrinkName" value="'+esc(draft.name)+'" placeholder="e.g. Sex on the Beach"></div><div class="pg-estimator-grid"><div class="pg-estimator-field"><label for="pgRecipeStatus">Status</label><select id="pgRecipeStatus">'+['Draft','Testing','Approved','Retired'].map(function(x){return '<option'+(draft.status===x?' selected':'')+'>'+x+'</option>';}).join('')+'</select></div><div class="pg-estimator-field"><label for="pgOutlet">Outlet (optional)</label><input id="pgOutlet" value="'+esc(draft.outlet)+'" placeholder="SBB, PP, Beach Buzz, Seasalt"></div><div class="pg-estimator-field"><label for="pgTargetVolume">Serving target (oz)</label><input id="pgTargetVolume" type="number" min="0.1" step="0.25" value="'+esc(draft.targetVolumeOz)+'"></div></div><div id="pgEstimatorIngredients">'+draft.ingredients.map(row).join('')+'</div><div class="pg-estimator-actions"><button id="pgEstimatorAdd" class="pg-estimator-btn secondary" type="button">+ Add Ingredient</button></div>'+(duplicateNames.length?'<p class="pg-estimator-note pg-estimator-error" role="status">Possible duplicate: '+esc(duplicateNames.join(', '))+'. Keep it if intentional.</p>':'')+'<div class="pg-estimator-grid"><div class="pg-estimator-field"><label for="pgPreparation">Preparation</label><input id="pgPreparation" value="'+esc(draft.preparation)+'"></div><div class="pg-estimator-field" style="grid-column:span 2"><label for="pgNotes">Notes</label><input id="pgNotes" value="'+esc(draft.notes)+'"></div></div>'+assumptions()+'<div class="pg-estimator-field"><label for="pgTarget">Target cost: <strong>'+esc(draft.target)+'%</strong></label><input id="pgTarget" class="pg-estimator-range" type="range" min="5" max="40" step="1" value="'+esc(draft.target)+'"><p class="pg-estimator-note">Move left for a lower cost percentage and higher selling price. Move right for a higher percentage and lower selling price.</p></div><div class="pg-estimator-field"><label for="pgMenuPrice">Actual menu price</label><input id="pgMenuPrice" type="number" min="0.01" step="0.25" value="'+esc(draft.menuPrice)+'"></div><div class="pg-estimator-results" aria-live="polite"><div class="pg-estimator-metrics">'+[['Recipe cost',money(c.missing.length?NaN:c.total)],['Recommended',money(c.suggested)],['Menu-friendly',money(c.menuFriendly)],['Actual cost %',c.actual==null?'—':c.actual.toFixed(1)+'%'],['Gross profit',money(c.gross)],['Alcohol',c.alcohol.toFixed(2)+' oz'],['Non-alcoholic',c.nonAlcoholic.toFixed(2)+' oz'],['Total liquid',c.liquid.toFixed(2)+' oz'],['From target',(c.difference>=0?'+':'')+c.difference.toFixed(2)+' oz']].map(function(x){return '<div class="pg-estimator-metric"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>';}).join('')+'</div><p class="pg-estimator-note">Ice, garnishes, cups, straws, and disposables are excluded from liquid volume. '+(Math.abs(c.difference)>.5?'This recipe is gently outside the approximately '+esc(c.targetVolume)+' oz guide.':'Volume is near the serving guide.')+'</p><details><summary>Ingredient cost breakdown</summary>'+c.breakdown.map(function(x){return '<p class="pg-estimator-note">'+esc(x.name)+' · '+esc(x.amount)+' '+esc(x.unit)+' · '+money(x.cost)+'</p>';}).join('')+'</details></div>'+(error?'<p class="pg-estimator-note pg-estimator-error" role="alert">'+esc(error)+'</p>':'')+'<div class="pg-estimator-actions"><button id="pgEstimatorSave" class="pg-estimator-btn" type="button">'+(draft.id?'Update saved recipe':'Save as recipe')+'</button><button id="pgEstimatorNew" class="pg-estimator-btn secondary" type="button">New estimate</button>'+(draft.id?'<button id="pgEstimatorDuplicate" class="pg-estimator-btn secondary" type="button">Duplicate recipe</button><button id="pgCopyRecipe" class="pg-estimator-btn secondary" type="button">Copy summary</button><button id="pgPrintCosting" class="pg-estimator-btn secondary" type="button">Print costing</button><button id="pgPrintCard" class="pg-estimator-btn secondary" type="button">Staff recipe card</button><button id="pgShareRecipe" class="pg-estimator-btn secondary" type="button">Share deliberately</button>':'')+'</div><section class="pg-estimator-saved"><h3>Saved Recipes</h3>'+recipes.map(function(x){var xc=calculate(x);return '<article'+(x.archivedAt?' style="opacity:.65"':'')+'><div><strong>'+esc(x.name)+'</strong><div class="pg-estimator-note">'+esc(x.status)+' · '+x.ingredients.length+' ingredients · '+money(xc.total)+' · v'+x.version+'</div></div><div><button class="pg-estimator-btn secondary" data-edit="'+x.id+'" type="button">Open</button> <button class="pg-estimator-btn secondary" data-compare="'+x.id+'" type="button">Compare</button> <button class="pg-estimator-btn secondary" data-archive="'+x.id+'" type="button">'+(x.archivedAt?'Restore':'Archive')+'</button></div></article>';}).join('')+'</section></section>';bind(root);}
